import{_ as a,c as o,o as t,ah as i}from"./chunks/framework.CKKOjZuE.js";const r="/moseq-reports/assets/FullWindow.DmqI9vF-.png",l="/moseq-reports/assets/Files.BvzYUseo.png",s="/moseq-reports/assets/mouse.B9g0-gOI.png",n="data:image/png;base64,",d="/moseq-reports/assets/Filters.CAi1qeGd.png",h="/moseq-reports/assets/History.KoAGNjj5.png",c="/moseq-reports/assets/View.CySiGQhy.png",q=JSON.parse('{"title":"Using Moseq Reports","description":"","frontmatter":{},"headers":[],"relativePath":"UsingMoseq.md","filePath":"UsingMoseq.md","lastUpdated":1749162497000}'),u={name:"UsingMoseq.md"};function p(m,e,f,g,y,w){return t(),o("div",null,e[0]||(e[0]=[i('<h1 id="using-moseq-reports" tabindex="-1">Using Moseq Reports <a class="header-anchor" href="#using-moseq-reports" aria-label="Permalink to &quot;Using Moseq Reports&quot;">​</a></h1><p><img src="'+r+'" alt="Full Window" data-zoomable="true"></p><h2 id="loading-data" tabindex="-1">Loading Data <a class="header-anchor" href="#loading-data" aria-label="Permalink to &quot;Loading Data&quot;">​</a></h2><p>You should have a file ending with the <code>*.msq</code> file extension. This file contains the data to be loaded into moseq-reports. There are several ways to trigger moseq-reports to load your file.</p><h3 id="from-the-main-menu" tabindex="-1">From the Main Menu <a class="header-anchor" href="#from-the-main-menu" aria-label="Permalink to &quot;From the Main Menu&quot;">​</a></h3><p>In the main application menu, click <code>File → Open Data</code>. A file load dialog will appear, allowing you to navigate and select your <code>*.msq</code> file. <img src="'+l+'" alt="File" data-zoomable="true"></p><h3 id="drag-and-drop" tabindex="-1">Drag and Drop <a class="header-anchor" href="#drag-and-drop" aria-label="Permalink to &quot;Drag and Drop&quot;">​</a></h3><p>The application allows you to drag and drop a <code>*.msq</code> file from your computers file explorer into the application window. Dropping the file within the window will trigger moseq-reports to load your file. <img src="'+s+'" alt="Drag and Drop" data-zoomable="true"></p><h3 id="file-associations" tabindex="-1">File Associations <a class="header-anchor" href="#file-associations" aria-label="Permalink to &quot;File Associations&quot;">​</a></h3><p>Upon install, moseq-reports will register the <code>*.msq</code> file extension with the operating system, associating it with the moseq-reports application. Afterwards, <code>*.msq</code> files should display in your file explorer with the mouse icon, and double clicking the file will load that <code>*.msq</code> file into moseq-reports. <img src="'+n+'" alt="msq file with icon" data-zoomable="true"></p><h2 id="data-filters" tabindex="-1">Data Filters <a class="header-anchor" href="#data-filters" aria-label="Permalink to &quot;Data Filters&quot;">​</a></h2><p>Data filters allow you to manipulate and filter data pulled from your <code>*.msq</code> file. Often you may want to display only a subset of groups in your visualization. To turn a group on or off, click the switch next to the group. You can reorder the groups by dragging/dropping the group row (grab at the vertical ellipsis). This will change the group order on plots that use this group order. There is also a color swatch next to each group name. The number within tells you the number of moseq sessions belong to that group. The color of the swatch indicates the color that will be used for that group throughout visualizations. You may change the default color by clicking on the swatch and selecting a new color from the color picker.</p><p>The data filter also keeps track of the current count method (<code>usage</code> or <code>frames</code>), as well as the currently selected syllable. Tools that display data from only one syllable will typically be bound to this value, and several tools may update this value when a particular piece of data is clicked on. The <code>Filter Syllable ID</code> box allows you to keep only a subset of syllables available for tools to display.</p><p>Upon loading an <code>*.msq</code> file into moseq-reports, the Data Filters pane in the application side bar will become active. To open or close the filters, click on the Filter button in the side bar. The default filter, typically named <code>filter0</code> will be added for you.</p><p>If you require additional filters (useful if you wanted to compare different group subsets, or say compare usage counting vs frames counting), you may always add another filter using the add button at the top right of the DAta Filters pane. Don&#39;t forget to bind your tools to the new data filter!</p><p><img src="'+d+'" alt="Data Filters" data-zoomable="true"></p><h2 id="notification-history" tabindex="-1">Notification History <a class="header-anchor" href="#notification-history" aria-label="Permalink to &quot;Notification History&quot;">​</a></h2><p>Also, the notification history lives in the application sidebar, activated by the clock button. This keeps a record of notifications shown to you since the application was started. If you miss a notification, or want more details, visit the notification history pane to review these message</p><p><img src="'+h+'" alt="Notification History" data-zoomable="true"></p><h2 id="layouts" tabindex="-1">Layouts <a class="header-anchor" href="#layouts" aria-label="Permalink to &quot;Layouts&quot;">​</a></h2><p>Layouts provide a way for you to save or load application state between different sessions of using moseq-reports. Layouts include information on the tool windows (layout, data, settings) as well as filters. When you first load your data into moseq-reports, the Default Layout will be applied. Layouts are stored as files ending with the <code>*.msl</code> file extension.</p><h3 id="loading-a-layout" tabindex="-1">Loading a Layout <a class="header-anchor" href="#loading-a-layout" aria-label="Permalink to &quot;Loading a Layout&quot;">​</a></h3><p>There are two ways to load a layout. The first is from the application main menu bar, select <code>View → Load Layout</code>. A file selection dialog will appear where you can select the layout file that you want to load. Clicking load will then load your layout file. Another way to load your layout file is to drag and drop your <code>*.msl</code> from your operating systems file explorer into the moseq-reports application window. In either case, the current layout will be cleared and your new layout will be applied.</p><p>The Default Layout contains a small number of common tools. The Default Layout can be loaded from the application main menu bar, select <code>View → Default Layout</code>. The current layout will be cleared and the default layout applied.</p><h3 id="saving-a-layout" tabindex="-1">Saving a Layout <a class="header-anchor" href="#saving-a-layout" aria-label="Permalink to &quot;Saving a Layout&quot;">​</a></h3><p>To save a layout, from the application main menu bar, select <code>View → Save Layout</code>. A file save dialog will appear, allowing you to select a file name and location to save your layout file</p><h3 id="clearing-the-current-layout" tabindex="-1">Clearing the Current Layout <a class="header-anchor" href="#clearing-the-current-layout" aria-label="Permalink to &quot;Clearing the Current Layout&quot;">​</a></h3><p>To clear the current layout, from the application main menu bar, select <code>View → Clear Layout</code>. All tool windows will be removed from the application.</p><p><img src="'+c+'" alt="View" data-zoomable="true"></p><h2 id="workspace-snapshots" tabindex="-1">Workspace Snapshots <a class="header-anchor" href="#workspace-snapshots" aria-label="Permalink to &quot;Workspace Snapshots&quot;">​</a></h2><p>You may take a snapshot of any individual tool window, but sometimes, you might want a snapshot of your entire moseq-reports workspace. The <code>Snapshot Workspace</code> command will render snapshots for all tool windows within the workspace and compose them together into a single image reflecting the relative positioning and sizes of all the tool windows.</p><p>To take a Workspace Snapshot, from the application main menu bar, select <code>View → Snapshot workspace</code>.</p><h2 id="other-functionality" tabindex="-1">Other functionality <a class="header-anchor" href="#other-functionality" aria-label="Permalink to &quot;Other functionality&quot;">​</a></h2><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><p>The tools are where the majority of the data will be viewed and are described in greater detail <a href="./Tools.html">here</a>.</p><h3 id="reloading-the-workspace" tabindex="-1">Reloading the workspace <a class="header-anchor" href="#reloading-the-workspace" aria-label="Permalink to &quot;Reloading the workspace&quot;">​</a></h3><p>Should a module become stuck, reloading the window will restart the application and will reset the current workspace. To reload, from the application main menu bar, select <code>View → Reload</code>.</p>',37)]))}const A=a(u,[["render",p]]);export{q as __pageData,A as default};
